import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"请求解析","description":"","frontmatter":{},"headers":[],"relativePath":"python/crawler/request.md","filePath":"python/crawler/request.md"}`),a={name:`python/crawler/request.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="请求解析" tabindex="-1">请求解析 <a class="header-anchor" href="#请求解析" aria-label="Permalink to “请求解析”">​</a></h1><ul><li>是指对客户端发送的请求进行解析，提取出请求的方法、URL、协议版本、请求头和请求体等信息。</li></ul><h2 id="http-协议" tabindex="-1">HTTP 协议 <a class="header-anchor" href="#http-协议" aria-label="Permalink to “HTTP 协议”">​</a></h2><ul><li>协议说明：超文本传输协议，默认端口为 80</li><li>传递报文：明文模式</li></ul><h2 id="https-协议" tabindex="-1">HTTPS 协议 <a class="header-anchor" href="#https-协议" aria-label="Permalink to “HTTPS 协议”">​</a></h2><ul><li>协议说明：http+ssl(安全套接层)，默认端口 443。比 http 协议更加安全。</li><li>传递报文：加密模式</li></ul><h2 id="请求头" tabindex="-1">请求头 <a class="header-anchor" href="#请求头" aria-label="Permalink to “请求头”">​</a></h2><p>客户端向服务发送请求所携带的参数</p><ul><li><code>Content-Type</code>：用来说明请求或响应中的实体数据的格式，告诉服务器如何解析数据。例如，Content-Type: application/json 表示以 JSON 格式传输数据，常用于前后端通信的 API 接口。</li><li><code>Accept</code>：告知服务器客户端希望接收的数据格式。如 Accept: application/json 表示期望返回 JSON 格式数据。</li><li><code>Authorization</code>：Authorization：用于认证，携带访问令牌或账号信息，表明客户端有权限访问资源。常见的值有<code>Bearer &lt;token&gt;</code>（JWT 或 OAuth 授权）和<code>Basic &lt;base64(username:password)&gt;</code>（基础认证）。</li><li><code>User-Agent</code>：标识客户端的类型和操作系统信息，服务器可据此做兼容性处理。</li><li><code>Referer</code>：告知服务器当前请求是从哪个页面跳转过来的，常用于防盗链或统计来源。</li><li><code>Cookie</code>：Cookie：携带客户端的 Cookie 信息，保持用户会话状态。</li><li><code>Accept-Language</code>：指定客户端希望接收的语言，用于国际化。如<code>Accept-Language:zh-CN,zh;q=0.9,en;q=0.8</code>表示优先接收中文，其次是英文。</li><li><code>Host</code>：指定目标服务器的域名，在虚拟主机环境中用于区分不同服务。</li><li><code>Cors</code>：标识请求的来源域名，用于 CORS 跨域资源共享验证。</li></ul><h2 id="响应头" tabindex="-1">响应头 <a class="header-anchor" href="#响应头" aria-label="Permalink to “响应头”">​</a></h2><p>服务器向客户端返回的信息</p><ul><li><p><code>Date</code>：响应的日期时间，格式为<code>Day, DD Mon YYYY HH:mm:ss GMT</code>。</p></li><li><p><code>Server</code>：服务器的软件信息，用于标识服务器类型。例如：<code>nginx/1.18.0</code>、<code>Apache/2.4.46</code>、<code>IIS/10.0</code>等。</p></li><li><p><code>Content-Type</code>：响应体的 MIME 类型和编码格式，是解析响应体的关键，常用值为<code>text/html</code>、<code>application/json</code>、<code>image/jpeg</code>等。</p></li><li><p><code>Content-Encoding</code>：响应体的压缩算法，客户端需先解压才能解析，常用值为<code>gzip</code>、<code>deflate</code>、<code>br</code>等。</p></li><li><p><code>Cache-Control</code>：指定响应的缓存控制，常用值为<code>no-cache</code>、<code>no-store</code>、<code>max-age</code>等。</p></li><li><p><code>Expires</code>：指定响应的过期时间，格式为<code>Day, DD Mon YYYY HH:mm:ss GMT</code>。</p></li><li><p><code>ETag</code>：资源的唯一标识（如哈希值），用于验证资源是否修改。</p></li><li><p><code>Access-Control-Allow-Origin</code>: 允许的来源域名，用于 CORS 跨域资源共享验证。</p></li><li><p><code>Set-Cookie</code>：服务器向客户端设置 Cookie，包含键值、过期时间、域名等信息</p></li></ul><h2 id="状态码" tabindex="-1">状态码 <a class="header-anchor" href="#状态码" aria-label="Permalink to “状态码”">​</a></h2><blockquote><p>1xx（信息性状态码）：请求已接收，继续处理</p></blockquote><ul><li>100 Continue：服务器已接收请求头，客户端可继续发送请求体（常用于 POST 大数据时的确认）。</li><li>101 Switching Protocols：服务器同意客户端的协议切换请求（如从 HTTP 切换到 WebSocket）。- 102 Processing：服务器正在处理请求，但尚未完成（常用于异步处理场景）。</li></ul><blockquote><p>2xx（成功状态码）：请求已成功处理</p></blockquote><ul><li>200：请求成功</li></ul><blockquote><p>3xx（重定向状态码）：请求需要进一步处理</p></blockquote><ul><li>301：永久重定向</li><li>302：临时重定向</li></ul><blockquote><p>4xx（客户端错误状态码）：请求包含错误语法或无法完成请求</p></blockquote><ul><li>400：请求错误</li><li>401：未授权</li><li>403：禁止访问</li><li>404：未找到</li></ul><blockquote><p>5xx（服务器错误状态码）：服务器处理请求出错</p></blockquote><ul><li>500：服务器错误</li><li>501：未实现</li><li>502：网关错误</li><li>503：服务不可用</li><li>504：网关超时</li><li>505：HTTP 版本不支持</li></ul>`,23)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};